<?php

namespace App\Http\Controllers;

use App\Models\TdsLiability;
use App\Models\User;
use Illuminate\Http\Request;

/** Read-only — TdsLiability rows are auto-generated by TdsLiabilityService on run approval. */
class TdsLiabilityController extends Controller
{
    private const VIEW_ROLES = User::PAYROLL_ACCESS_ROLES;

    public function index(Request $request)
    {
        if (! in_array($request->user()->role, self::VIEW_ROLES, true)) {
            return response()->json(['message' => 'Forbidden'], 403);
        }

        $query = TdsLiability::with('employee:id,full_name,employee_code,pan_tax_id', 'allocations.challan');

        if ($request->filled('employee_id')) {
            $query->where('employee_id', $request->query('employee_id'));
        }
        if ($request->filled('financial_year')) {
            $query->where('financial_year', $request->query('financial_year'));
        }
        if ($request->filled('quarter')) {
            $query->where('quarter', $request->query('quarter'));
        }
        if ($request->filled('status')) {
            $query->where('status', $request->query('status'));
        }

        return response()->json($query->orderByDesc('period')->get());
    }

    public function show(Request $request, $id)
    {
        if (! in_array($request->user()->role, self::VIEW_ROLES, true)) {
            return response()->json(['message' => 'Forbidden'], 403);
        }

        return response()->json(
            TdsLiability::with('employee:id,full_name,employee_code,pan_tax_id', 'allocations.challan')->findOrFail($id)
        );
    }
}
